-- PROPOSED — NOT APPLIED. REQUIRES OWNER APPROVAL OF THE WORDING (tmp/conversation-v3/EN_ES_COPY_REVIEW.md)
-- AND NATIVE REVIEW OF EVERY NON-EN/ES ROW BEFORE ANY ROW IS ACTIVATED.
--
-- SELLER CONVERSATION MACHINE v3 (owner brief 2026-10-06 late): 216 sms_templates rows,
-- 10 NEW use cases × 16 languages (160 rows) + 56 rows for EXISTING use cases
-- that had no row at all in a language (ask_condition_clarifier, seller_frustration_apology,
-- not_interested, already_listed, text_only_redirect, future_nurture):
--   v3_price_far_above_nurture: Asking price far above our value (> 1.5x or > value + $100K), or an implausible ask. No condition ask; thread goes to 30-day nurture.
--   v3_below_value_condition_occupancy: Asking price below our value (< 90% of value), condition AND occupancy both still unknown. Next: the offer path.
--   v3_occupancy_check: Condition known, occupancy unknown (any price branch except far-above).
--   v3_referral_best_contact: Non-owner / manager / family member, no phone number in the reply (with a number: the existing referral automation captures it). Asked once; a second non-answer archives the property pairing.
--   v3_reask_ownership: Unreadable / off-topic reply to the ownership question. Sent once; a second miss archives.
--   v3_reask_interest: Unreadable / off-topic reply to the proposal question. Sent once; a second miss archives.
--   v3_who_is_this_variant: Second who/why/how-did-you-get-my-number in a thread when info_source_explanation has no row in the language. A third ask is archived.
--   v3_numbers_pending: All five checklist facts collected but no offer-ready engine number yet. No number is quoted; the thread waits for the engine.
--   v3_update_year_follow_up: A generic condition answer ("good shape", "it's updated") with no update years and no major repairs. Asked once.
--   v3_mf_per_door_anchor: Multifamily, checklist complete, >= 3 non-outlier MF door comps (<= 3 mi, <= 18 mo, off-market preferred) and an authoritative MAO; range capped at MAO per door. Needs renderer support for {{per_door_low}}/{{per_door_high}} before it can send.
--
-- SAFE TO APPLY EARLY: every row is INACTIVE (is_active = false) AND
-- safe_for_auto_reply = false. The auto-reply selector reads only active + safe
-- rows, and only the SELLER_CONVERSATION_V3 layer (env flag, default OFF, on top
-- of SELLER_AUTOPILOT_V2) names these use cases. Nothing can send from this file.
--
-- v3_mf_per_door_anchor uses {{per_door_low}} / {{per_door_high}}, which the
-- renderer does not support yet (render-template.js ALLOWED_TEMPLATE_PLACEHOLDERS):
-- that row fails closed until the renderer + negotiation quote log accept a range.
--
-- Activate per row after approval:
--   update public.sms_templates set is_active = true, safe_for_auto_reply = true, updated_at = now()
--    where template_id in (...approved ids...);
-- Idempotent: inserts only template_ids that do not exist yet.

begin;
set local lock_timeout = '5s';

insert into public.sms_templates (
  use_case, template_id, template_name, language, agent_persona, template_body,
  english_translation, variables, is_active, safe_for_auto_reply, reply_mode,
  identity_contact_mode, property_type_scope, stage_code, stage_label,
  is_first_touch, is_follow_up, fallback_rank, quarantine_state, metadata
)
select v.use_case, v.template_id, v.template_name, v.language, 'Alex', v.template_body,
       v.english_translation, '{}'::jsonb,
       false, false, 'auto',
       'neutral', case when v.use_case = 'v3_mf_per_door_anchor' then 'Multifamily' else 'Residential' end,
       v.stage_code, v.stage_label,
       false, false, 1, 'active',
       jsonb_build_object(
         'authored_by', 'seller_conversation_v3_2026_10_06',
         'approval_status', 'proposed_pending_owner_approval',
         'native_review', v.native_review,
         'proposal_kind', v.kind,
         'flag', 'SELLER_CONVERSATION_V3'
       )
from (values
  ('v3_price_far_above_nurture', 'lc-v3-fan-en-1', 'v3_price_far_above_nurture — English (seller conversation v3)', 'English', 'Thanks for being straight with me. That''s a good bit above where the numbers work for me, so I won''t waste your time. If you''re ever seriously considering an offer, just let me know.', null, 'S3', 'Stage 3 Price Far Above Value (nurture)', false, 'new_use_case'),
  ('v3_price_far_above_nurture', 'lc-v3-fan-es-1', 'v3_price_far_above_nurture — Spanish (seller conversation v3)', 'Spanish', 'Gracias por ser directo conmigo. Eso está bastante por encima de donde me dan los números, así que no le quito su tiempo. Si en algún momento considera en serio una oferta, avíseme.', 'Thanks for being straight with me. That''s a good bit above where the numbers work for me, so I won''t waste your time. If you''re ever seriously considering an offer, just let me know.', 'S3', 'Stage 3 Price Far Above Value (nurture)', false, 'new_use_case'),
  ('v3_price_far_above_nurture', 'lc-v3-fan-pt-1', 'v3_price_far_above_nurture — Portuguese (seller conversation v3)', 'Portuguese', 'Obrigado pela sinceridade. Isso está bem acima de onde os números funcionam para mim, então não vou tomar seu tempo. Se algum dia considerar uma oferta a sério, é só me avisar.', 'Thanks for being straight with me. That''s a good bit above where the numbers work for me, so I won''t waste your time. If you''re ever seriously considering an offer, just let me know.', 'S3', 'Stage 3 Price Far Above Value (nurture)', true, 'new_use_case'),
  ('v3_price_far_above_nurture', 'lc-v3-fan-fr-1', 'v3_price_far_above_nurture — French (seller conversation v3)', 'French', 'Merci d''être franc. C''est nettement au-dessus de ce qui fonctionne pour moi, donc je ne vais pas vous faire perdre votre temps. Si un jour vous envisagez sérieusement une offre, faites-moi signe.', 'Thanks for being straight with me. That''s a good bit above where the numbers work for me, so I won''t waste your time. If you''re ever seriously considering an offer, just let me know.', 'S3', 'Stage 3 Price Far Above Value (nurture)', true, 'new_use_case'),
  ('v3_price_far_above_nurture', 'lc-v3-fan-de-1', 'v3_price_far_above_nurture — German (seller conversation v3)', 'German', 'Danke für die offene Antwort. Das liegt deutlich über dem, was für mich rechnerisch geht, also will ich Ihre Zeit nicht verschwenden. Wenn Sie ein Angebot einmal ernsthaft in Betracht ziehen, melden Sie sich einfach.', 'Thanks for being straight with me. That''s a good bit above where the numbers work for me, so I won''t waste your time. If you''re ever seriously considering an offer, just let me know.', 'S3', 'Stage 3 Price Far Above Value (nurture)', true, 'new_use_case'),
  ('v3_price_far_above_nurture', 'lc-v3-fan-it-1', 'v3_price_far_above_nurture — Italian (seller conversation v3)', 'Italian', 'Grazie della sincerità. È parecchio sopra a dove i numeri funzionano per me, quindi non le faccio perdere tempo. Se un giorno valuterà seriamente un''offerta, me lo faccia sapere.', 'Thanks for being straight with me. That''s a good bit above where the numbers work for me, so I won''t waste your time. If you''re ever seriously considering an offer, just let me know.', 'S3', 'Stage 3 Price Far Above Value (nurture)', true, 'new_use_case'),
  ('v3_price_far_above_nurture', 'lc-v3-fan-pl-1', 'v3_price_far_above_nurture — Polish (seller conversation v3)', 'Polish', 'Dzięki za szczerość. To sporo powyżej tego, co mi się kalkuluje, więc nie będę zabierać Panu czasu. Jeśli kiedyś poważnie rozważy Pan ofertę, proszę dać znać.', 'Thanks for being straight with me. That''s a good bit above where the numbers work for me, so I won''t waste your time. If you''re ever seriously considering an offer, just let me know.', 'S3', 'Stage 3 Price Far Above Value (nurture)', true, 'new_use_case'),
  ('v3_price_far_above_nurture', 'lc-v3-fan-vi-1', 'v3_price_far_above_nurture — Vietnamese (seller conversation v3)', 'Vietnamese', 'Cảm ơn anh/chị đã nói thẳng. Mức đó cao hơn khá nhiều so với con số tôi có thể làm, nên tôi không muốn làm mất thời gian của anh/chị. Khi nào anh/chị thật sự cân nhắc một lời đề nghị, cứ báo tôi nhé.', 'Thanks for being straight with me. That''s a good bit above where the numbers work for me, so I won''t waste your time. If you''re ever seriously considering an offer, just let me know.', 'S3', 'Stage 3 Price Far Above Value (nurture)', true, 'new_use_case'),
  ('v3_price_far_above_nurture', 'lc-v3-fan-zh-1', 'v3_price_far_above_nurture — Mandarin (seller conversation v3)', 'Mandarin', '谢谢您直说。这个价格比我能做到的高出不少，所以我就不耽误您的时间了。如果您哪天认真考虑报价，随时告诉我。', 'Thanks for being straight with me. That''s a good bit above where the numbers work for me, so I won''t waste your time. If you''re ever seriously considering an offer, just let me know.', 'S3', 'Stage 3 Price Far Above Value (nurture)', true, 'new_use_case'),
  ('v3_price_far_above_nurture', 'lc-v3-fan-ko-1', 'v3_price_far_above_nurture — Korean (seller conversation v3)', 'Korean', '솔직하게 말씀해 주셔서 감사합니다. 제가 맞출 수 있는 금액보다 꽤 높아서 시간을 뺏지 않겠습니다. 나중에 제안을 진지하게 고려하시게 되면 언제든 알려 주세요.', 'Thanks for being straight with me. That''s a good bit above where the numbers work for me, so I won''t waste your time. If you''re ever seriously considering an offer, just let me know.', 'S3', 'Stage 3 Price Far Above Value (nurture)', true, 'new_use_case'),
  ('v3_price_far_above_nurture', 'lc-v3-fan-ja-1', 'v3_price_far_above_nurture — Japanese (seller conversation v3)', 'Japanese', '率直に教えていただきありがとうございます。こちらで合わせられる金額よりかなり上なので、お時間を取らせないようにします。本気でオファーを検討される時が来たら、いつでもご連絡ください。', 'Thanks for being straight with me. That''s a good bit above where the numbers work for me, so I won''t waste your time. If you''re ever seriously considering an offer, just let me know.', 'S3', 'Stage 3 Price Far Above Value (nurture)', true, 'new_use_case'),
  ('v3_price_far_above_nurture', 'lc-v3-fan-he-1', 'v3_price_far_above_nurture — Hebrew (seller conversation v3)', 'Hebrew', 'תודה על הכנות. זה די הרבה מעל מה שהמספרים מאפשרים לי, אז לא אבזבז לך את הזמן. אם תשקול ברצינות הצעה בעתיד, פשוט תודיע לי.', 'Thanks for being straight with me. That''s a good bit above where the numbers work for me, so I won''t waste your time. If you''re ever seriously considering an offer, just let me know.', 'S3', 'Stage 3 Price Far Above Value (nurture)', true, 'new_use_case'),
  ('v3_price_far_above_nurture', 'lc-v3-fan-ar-1', 'v3_price_far_above_nurture — Arabic (seller conversation v3)', 'Arabic', 'شكراً لصراحتك. هذا أعلى بكثير مما تسمح به الأرقام بالنسبة لي، لذلك لن أضيع وقتك. إذا فكرت بجدية في عرض يوماً ما، فقط أخبرني.', 'Thanks for being straight with me. That''s a good bit above where the numbers work for me, so I won''t waste your time. If you''re ever seriously considering an offer, just let me know.', 'S3', 'Stage 3 Price Far Above Value (nurture)', true, 'new_use_case'),
  ('v3_price_far_above_nurture', 'lc-v3-fan-ru-1', 'v3_price_far_above_nurture — Russian (seller conversation v3)', 'Russian', 'Спасибо за прямоту. Это заметно выше того, что у меня сходится по цифрам, так что не буду отнимать ваше время. Если когда-нибудь всерьёз захотите рассмотреть предложение, просто напишите.', 'Thanks for being straight with me. That''s a good bit above where the numbers work for me, so I won''t waste your time. If you''re ever seriously considering an offer, just let me know.', 'S3', 'Stage 3 Price Far Above Value (nurture)', true, 'new_use_case'),
  ('v3_price_far_above_nurture', 'lc-v3-fan-el-1', 'v3_price_far_above_nurture — Greek (seller conversation v3)', 'Greek', 'Ευχαριστώ για την ειλικρίνεια. Αυτό είναι αρκετά πάνω από εκεί που βγαίνουν τα νούμερα για μένα, οπότε δεν θα σας χάσω τον χρόνο. Αν ποτέ σκεφτείτε σοβαρά μια προσφορά, απλώς ενημερώστε με.', 'Thanks for being straight with me. That''s a good bit above where the numbers work for me, so I won''t waste your time. If you''re ever seriously considering an offer, just let me know.', 'S3', 'Stage 3 Price Far Above Value (nurture)', true, 'new_use_case'),
  ('v3_price_far_above_nurture', 'lc-v3-fan-hi-1', 'v3_price_far_above_nurture — Indian (Hindi or Other) (seller conversation v3)', 'Indian (Hindi or Other)', 'साफ़ बताने के लिए धन्यवाद। यह मेरे हिसाब से काफ़ी ऊपर है, इसलिए मैं आपका समय बर्बाद नहीं करूँगा। अगर कभी आप किसी ऑफ़र पर गंभीरता से विचार करें, तो बस मुझे बता दीजिए।', 'Thanks for being straight with me. That''s a good bit above where the numbers work for me, so I won''t waste your time. If you''re ever seriously considering an offer, just let me know.', 'S3', 'Stage 3 Price Far Above Value (nurture)', true, 'new_use_case'),
  ('v3_below_value_condition_occupancy', 'lc-v3-bvco-en-1', 'v3_below_value_condition_occupancy — English (seller conversation v3)', 'English', 'Thanks, that could work. Two quick things: what shape is the place in, and is anyone living there right now?', null, 'S4', 'Stage 4 Below-Value Condition + Occupancy', false, 'new_use_case'),
  ('v3_below_value_condition_occupancy', 'lc-v3-bvco-es-1', 'v3_below_value_condition_occupancy — Spanish (seller conversation v3)', 'Spanish', 'Gracias, eso podría funcionar. Dos cositas rápidas: ¿en qué condición está la casa, y vive alguien ahí ahorita?', 'Thanks, that could work. Two quick things: what shape is the place in, and is anyone living there right now?', 'S4', 'Stage 4 Below-Value Condition + Occupancy', false, 'new_use_case'),
  ('v3_below_value_condition_occupancy', 'lc-v3-bvco-pt-1', 'v3_below_value_condition_occupancy — Portuguese (seller conversation v3)', 'Portuguese', 'Obrigado, isso pode funcionar. Duas perguntas rápidas: em que estado está o imóvel, e tem alguém morando lá agora?', 'Thanks, that could work. Two quick things: what shape is the place in, and is anyone living there right now?', 'S4', 'Stage 4 Below-Value Condition + Occupancy', true, 'new_use_case'),
  ('v3_below_value_condition_occupancy', 'lc-v3-bvco-fr-1', 'v3_below_value_condition_occupancy — French (seller conversation v3)', 'French', 'Merci, ça pourrait marcher. Deux petites questions : dans quel état est le bien, et est-ce que quelqu''un y habite en ce moment ?', 'Thanks, that could work. Two quick things: what shape is the place in, and is anyone living there right now?', 'S4', 'Stage 4 Below-Value Condition + Occupancy', true, 'new_use_case'),
  ('v3_below_value_condition_occupancy', 'lc-v3-bvco-de-1', 'v3_below_value_condition_occupancy — German (seller conversation v3)', 'German', 'Danke, das könnte passen. Zwei kurze Fragen: In welchem Zustand ist das Haus, und wohnt gerade jemand dort?', 'Thanks, that could work. Two quick things: what shape is the place in, and is anyone living there right now?', 'S4', 'Stage 4 Below-Value Condition + Occupancy', true, 'new_use_case'),
  ('v3_below_value_condition_occupancy', 'lc-v3-bvco-it-1', 'v3_below_value_condition_occupancy — Italian (seller conversation v3)', 'Italian', 'Grazie, potrebbe funzionare. Due domande veloci: in che condizioni è la casa, e ci abita qualcuno adesso?', 'Thanks, that could work. Two quick things: what shape is the place in, and is anyone living there right now?', 'S4', 'Stage 4 Below-Value Condition + Occupancy', true, 'new_use_case'),
  ('v3_below_value_condition_occupancy', 'lc-v3-bvco-pl-1', 'v3_below_value_condition_occupancy — Polish (seller conversation v3)', 'Polish', 'Dzięki, to może się udać. Dwa szybkie pytania: w jakim stanie jest nieruchomość i czy ktoś tam teraz mieszka?', 'Thanks, that could work. Two quick things: what shape is the place in, and is anyone living there right now?', 'S4', 'Stage 4 Below-Value Condition + Occupancy', true, 'new_use_case'),
  ('v3_below_value_condition_occupancy', 'lc-v3-bvco-vi-1', 'v3_below_value_condition_occupancy — Vietnamese (seller conversation v3)', 'Vietnamese', 'Cảm ơn, mức đó có thể được. Cho tôi hỏi nhanh hai điều: nhà đang ở tình trạng thế nào, và hiện có ai đang ở không?', 'Thanks, that could work. Two quick things: what shape is the place in, and is anyone living there right now?', 'S4', 'Stage 4 Below-Value Condition + Occupancy', true, 'new_use_case'),
  ('v3_below_value_condition_occupancy', 'lc-v3-bvco-zh-1', 'v3_below_value_condition_occupancy — Mandarin (seller conversation v3)', 'Mandarin', '谢谢，这个价格可能可以。快速问两件事：房子现在状况怎么样？现在有人住吗？', 'Thanks, that could work. Two quick things: what shape is the place in, and is anyone living there right now?', 'S4', 'Stage 4 Below-Value Condition + Occupancy', true, 'new_use_case'),
  ('v3_below_value_condition_occupancy', 'lc-v3-bvco-ko-1', 'v3_below_value_condition_occupancy — Korean (seller conversation v3)', 'Korean', '감사합니다, 그 정도면 가능할 수도 있겠네요. 두 가지만 여쭤볼게요. 집 상태는 어떤가요? 지금 누가 살고 있나요?', 'Thanks, that could work. Two quick things: what shape is the place in, and is anyone living there right now?', 'S4', 'Stage 4 Below-Value Condition + Occupancy', true, 'new_use_case'),
  ('v3_below_value_condition_occupancy', 'lc-v3-bvco-ja-1', 'v3_below_value_condition_occupancy — Japanese (seller conversation v3)', 'Japanese', 'ありがとうございます、その金額なら合うかもしれません。2点だけ教えてください。物件の状態はいかがですか？今どなたか住んでいますか？', 'Thanks, that could work. Two quick things: what shape is the place in, and is anyone living there right now?', 'S4', 'Stage 4 Below-Value Condition + Occupancy', true, 'new_use_case'),
