  ('v3_occupancy_check', 'lc-v3-occ-es-1', 'v3_occupancy_check — Spanish (seller conversation v3)', 'Spanish', 'Entendido, gracias. ¿Vive alguien ahí ahorita, o está desocupada?', 'Got it, thanks. Is anyone living there right now, or is it vacant?', 'S4', 'Stage 4 Occupancy', false, 'new_use_case'),
